function fig77(el) {
  const svg = $('svg', el), zones = $$('.f77-zone', svg);
  const card = infoCard(el, JSON.parse($('.nf-info', el).textContent));
  const popup = $('.nf-card', el);
  let active = null, pinned = null, leaveTimer;

  function place(zone) {
    const hit = $('.f77-hit', zone);
    card.show(zone.dataset.k, hit);
    const a = hit.getBoundingClientRect(), b = popup.getBoundingClientRect();
    if (b.left < a.right && b.right > a.left && b.top < a.bottom && b.bottom > a.top) {
      const frame = el.getBoundingClientRect();
      const above = a.top - frame.top - b.height - 8;
      popup.style.top = `${above >= 4 ? above : a.bottom - frame.top + 8}px`;
    }
  }

  function inspect(zone) {
    clearTimeout(leaveTimer);
    active = zone;
    el.classList.toggle('is-focus', !!zone);
    zones.forEach(item => item.classList.toggle('is-on', item === zone));
    if (zone) place(zone);
    else card.hide();
  }

  function setPinned(zone) {
    pinned = zone;
    zones.forEach(item => item.setAttribute('aria-pressed', String(item === pinned)));
    inspect(zone);
  }

  function scheduleLeave() {
    clearTimeout(leaveTimer);
    leaveTimer = setTimeout(() => {
      if (!pinned && !popup.matches(':hover') && !active?.matches(':focus-visible')) inspect(null);
    }, 90);
  }

  zones.forEach((zone, index) => {
    zone.addEventListener('pointerenter', event => {
      if (!pinned && event.pointerType !== 'touch') inspect(zone);
    });
    zone.addEventListener('pointerleave', scheduleLeave);
    zone.addEventListener('focus', () => { if (!pinned) inspect(zone); });
    zone.addEventListener('blur', scheduleLeave);
    zone.addEventListener('click', () => setPinned(pinned === zone ? null : zone));
    zone.addEventListener('keydown', event => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        setPinned(pinned === zone ? null : zone);
      }
      const step = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 }[event.key];
      if (step) {
        event.preventDefault();
        const next = zones[(index + step + zones.length) % zones.length];
        if (pinned) setPinned(next);
        next.focus();
      }
    });
  });
  el.addEventListener('nf-leave', scheduleLeave);
  el.addEventListener('keydown', event => { if (event.key === 'Escape') setPinned(null); });
  document.addEventListener('click', event => {
    if (active && !el.contains(event.target)) setPinned(null);
  });
  new ResizeObserver(() => { if (active) place(active); }).observe(el);

  const routes = $$('.f77-route, .f77-flow', svg).map((path, index) => {
    const pulse = document.createElementNS(NS, 'circle');
    pulse.setAttribute('class', 'f77-pulse');
    pulse.setAttribute('r', '3.4');
    pulse.setAttribute('opacity', '0');
    pulse.style.fill = getComputedStyle(path).stroke;
    path.parentNode.insertBefore(pulse, $('.f77-hit', path.parentNode));
    return { path, pulse, length: path.getTotalLength(), delay: index * 170 };
  });
  const road = $('image[href$="road-attention.png"]', svg);
  clock(el, time => {
    road.style.opacity = String(.94 + .06 * Math.sin(time / 950));
    routes.forEach(({ path, pulse, length, delay }) => {
      if (path.classList.contains('f77-dashed')) path.style.strokeDashoffset = String(-time / 95);
      const progress = ((time - delay) % 2400 + 2400) % 2400 / 2400;
      const point = path.getPointAtLength(length * progress);
      pulse.setAttribute('cx', point.x);
      pulse.setAttribute('cy', point.y);
      pulse.setAttribute('opacity', Math.min(1, progress * 15, (1 - progress) * 15));
    });
  });
}

