function fig75(el) {
  const svg = $('svg', el), zones = $$('.f75-zone', svg);
  const card = infoCard(el, JSON.parse($('.nf-info', el).textContent));
  const popup = $('.nf-card', el);
  const show = g => {
    const hit = $('.f75-hit', g);
    card.show(g.dataset.k, hit);
    const a = hit.getBoundingClientRect(), b = popup.getBoundingClientRect();
    if (b.left < a.right && b.right > a.left && b.top < a.bottom && b.bottom > a.top) {
      const frame = el.getBoundingClientRect();
      const above = a.top - frame.top - b.height - 8;
      popup.style.top = `${above >= 4 ? above : a.bottom - frame.top + 8}px`;
    }
  };
  const routes = $$('.f75-route, .f75-flow', svg).map((path, i) => {
    const pulse = document.createElementNS(NS, 'circle');
    pulse.setAttribute('class', 'f75-pulse'); pulse.setAttribute('r', '3.2');
    pulse.setAttribute('opacity', '0');
    pulse.style.fill = getComputedStyle(path).stroke;
    path.parentNode.insertBefore(pulse, $('.f75-hit', path.parentNode));
    return {path, pulse, length:path.getTotalLength(), delay:i*210};
  });
  clock(el, t => { routes.forEach(({path,pulse,halo,length,delay}) => {
    if(path.classList.contains('f75-dashed')) path.style.strokeDashoffset=String(-t/95);
    const q=path.getPointAtLength(length*(((t-delay)%2800+2800)%2800)/2800);
    pulse.setAttribute('cx',q.x); pulse.setAttribute('cy',q.y); pulse.setAttribute('opacity','1');
  });});
  let pinned=null, inspected=null, leaveTimer;
  const release=()=>{
    if(pinned||el.classList.contains('is-card')) return;
    clearTimeout(leaveTimer); inspected=null; el.classList.remove('is-focus');
    zones.forEach(g=>g.classList.remove('is-on')); card.hide();
  };
  const inspect=g=>{
    clearTimeout(leaveTimer); inspected=g; el.classList.add('is-focus');
    zones.forEach(n=>n.classList.toggle('is-on',n===g)); show(g);
  };
  const clear=()=>{pinned=null;el.classList.remove('is-card');zones.forEach(g=>g.setAttribute('aria-pressed','false'));release();};
  const pin=g=>{
    pinned=pinned===g?null:g; zones.forEach(n=>n.setAttribute('aria-pressed',String(n===pinned)));
    if(pinned){el.classList.add('is-card');inspect(g);}else{el.classList.remove('is-card');release();}
  };
  zones.forEach(g=>{
    g.addEventListener('pointerenter',()=>{if(!pinned)inspect(g);});
    g.addEventListener('pointerleave',()=>{if(!g.matches(':focus-visible')) leaveTimer=setTimeout(release,90);});
    g.addEventListener('focus',()=>{if(!pinned)inspect(g);});
    g.addEventListener('blur',()=>{leaveTimer=setTimeout(release,90);});
    g.addEventListener('click',()=>pin(g));
    g.addEventListener('keydown',e=>{
      if(e.key==='Enter'||e.key===' '){e.preventDefault();pin(g);}
      if(['ArrowRight','ArrowDown','ArrowLeft','ArrowUp'].includes(e.key)){
        e.preventDefault();const step=['ArrowRight','ArrowDown'].includes(e.key)?1:-1;
        zones[(zones.indexOf(g)+step+zones.length)%zones.length].focus();
      }
    });
  });
  el.addEventListener('nf-leave',()=>{leaveTimer=setTimeout(release,90);});
  window.addEventListener('resize',()=>{if(inspected)show(inspected);});
  el.addEventListener('keydown',e=>{if(e.key==='Escape')clear();});
  document.addEventListener('click',e=>{if(pinned&&!el.contains(e.target))clear();});
}

