// ================================================================ Fig. 7.13
function fig713(el) {
  if (el.classList.contains('f713-redraw')) { fig713Redraw(el); return; }
  const svg = $('svg', el), info = JSON.parse($('.nf-info', el).textContent);
  const card = infoCard(el, info), groups = $$('[data-k]', svg);
  const token = $('.token', svg), G = k => groups.find(g => g.dataset.k === k);
  const stages = [
    { k: 'agent', d: 850 }, { k: 'action', d: 1600, path: true },
    { k: 'env', d: 850 }, { k: 'next', d: 900, path: true },
    { k: 'current', d: 1100, path: true },
  ];
  const total = stages.reduce((sum, s) => sum + s.d, 0);
  let live = null;
  let pinned = null, inspected = null, leaveTimer = 0;
  const draw = t => {
    let x = t % total, i = 0;
    while (x >= stages[i].d) { x -= stages[i].d; i++; }
    const stage = stages[i], group = G(stage.k);
    if (live !== group) {
      live?.classList.remove('is-live'); group.classList.add('is-live'); live = group;
    }
    token.classList.toggle('on', !!stage.path);
    if (stage.path) {
      const pt = along($('.shaft', group), x / stage.d);
      token.setAttribute('cx', pt.x); token.setAttribute('cy', pt.y);
    }
  };
  const clk = clock(el, draw);
  if (!reduce) draw(0);
  const inspect = g => {
    clearTimeout(leaveTimer);
    inspected = g; el.classList.add('is-inspecting', 'is-focus');
    groups.forEach(n => n.classList.toggle('is-on', n === g));
    clk.hold(true);
    card.show(g.dataset.k, g);
  };
  const release = () => {
    if (pinned || el.classList.contains('is-card')) return;
    clearTimeout(leaveTimer);
    inspected = null; el.classList.remove('is-inspecting', 'is-focus');
    groups.forEach(g => g.classList.remove('is-on'));
    clk.hold(false); card.hide();
  };
  const clearPin = () => {
    pinned = null; groups.forEach(g => g.setAttribute('aria-pressed', 'false')); release();
  };
  const pin = g => {
    pinned = pinned === g ? null : g;
    groups.forEach(n => n.setAttribute('aria-pressed', String(n === pinned)));
    if (pinned) inspect(g); else release();
  };
  for (const g of groups) {
    g.addEventListener('pointerenter', () => { if (!pinned) inspect(g); });
    g.addEventListener('pointerleave', () => {
      if (document.activeElement !== g) leaveTimer = setTimeout(() => { if (inspected === g) release(); }, 80);
    });
    g.addEventListener('focus', () => { if (!pinned) inspect(g); });
    g.addEventListener('blur', release);
    g.addEventListener('click', () => pin(g));
    g.addEventListener('keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); pin(g); }
    });
  }
  el.addEventListener('nf-leave', release);
  el.addEventListener('keydown', e => { if (e.key === 'Escape') clearPin(); });
  document.addEventListener('click', e => { if (!el.contains(e.target)) clearPin(); });
}

function figRLWorkflow(el) {
  const svg = $('svg', el), zones = $$('.rl-zone', svg);
  const card = infoCard(el, JSON.parse($('.nf-info', el).textContent));
  const popup = $('.nf-card', el);
  let active = null, pinned = null, leaveTimer;

  function place(zone) {
    const hit = $('.rl-hit', zone);
    card.show(zone.dataset.k, hit);
    const a = hit.getBoundingClientRect(), b = popup.getBoundingClientRect();
    if (b.left < a.right && b.right > a.left && b.top < a.bottom && b.bottom > a.top) {
      const frame = el.getBoundingClientRect();
      const above = a.top - frame.top - b.height - 8;
      popup.style.top = `${above >= 4 ? above : a.bottom - frame.top + 8}px`;
    }
  }
  function inspect(zone) {
    clearTimeout(leaveTimer);
    active = zone;
    el.classList.toggle('is-focus', !!zone);
    zones.forEach(item => item.classList.toggle('is-on', item === zone));
    if (zone) place(zone); else card.hide();
  }
  function setPinned(zone) {
    pinned = zone;
    zones.forEach(item => item.setAttribute('aria-pressed', String(item === pinned)));
    inspect(zone);
  }
  function scheduleLeave() {
    clearTimeout(leaveTimer);
    leaveTimer = setTimeout(() => {
      if (!pinned && !popup.matches(':hover') && !active?.matches(':focus-visible')) inspect(null);
    }, 90);
  }
  zones.forEach((zone, index) => {
    zone.addEventListener('pointerenter', event => { if (!pinned && event.pointerType !== 'touch') inspect(zone); });
    zone.addEventListener('pointerleave', scheduleLeave);
    zone.addEventListener('focus', () => { if (!pinned) inspect(zone); });
    zone.addEventListener('blur', scheduleLeave);
    zone.addEventListener('click', () => setPinned(pinned === zone ? null : zone));
    zone.addEventListener('keydown', event => {
      if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); setPinned(pinned === zone ? null : zone); }
      const step = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 }[event.key];
      if (step) { event.preventDefault(); const next = zones[(index + step + zones.length) % zones.length]; if (pinned) setPinned(next); next.focus(); }
    });
  });
  el.addEventListener('nf-leave', scheduleLeave);
  el.addEventListener('keydown', event => { if (event.key === 'Escape') setPinned(null); });
  document.addEventListener('click', event => { if (active && !el.contains(event.target)) setPinned(null); });
  new ResizeObserver(() => { if (active) place(active); }).observe(el);

  const routes = $$('.rl-route', svg).flatMap((path, index) => {
    const directions = path.dataset.bidirectional === 'true' ? [false, true] : [false];
    return directions.map(reverse => {
      const pulse = document.createElementNS(NS, 'circle');
      pulse.setAttribute('class', 'rl-pulse'); pulse.style.fill = getComputedStyle(path).stroke; pulse.setAttribute('r', '7'); pulse.setAttribute('opacity', '0');
      const halo = document.createElementNS(NS, 'circle');
      halo.setAttribute('class', 'rl-glow'); halo.setAttribute('r', '18'); halo.setAttribute('opacity', '0');
      path.parentNode.insertBefore(halo, $('.rl-hit', path.parentNode));
      path.parentNode.insertBefore(pulse, $('.rl-hit', path.parentNode));
      const duration = Number(path.dataset.duration) || 2100;
      const travel = Number(path.dataset.travel) || duration;
      return { path, pulse, halo, reverse, length: path.getTotalLength(), delay: index * 180, duration, travel };
    });
  });
  if (!routes.length) return;
  clock(el, time => routes.forEach(({ path, pulse, halo, reverse, length, delay, duration, travel }) => {
    const progress = Math.min(1, ((time - delay) % duration + duration) % duration / travel);
    const point = path.getPointAtLength(length * (reverse ? 1 - progress : progress));
    const opacity = Math.min(1, progress * 15, (1 - progress) * 15);
    for (const light of [halo, pulse]) {
      light.setAttribute('cx', point.x); light.setAttribute('cy', point.y);
      light.setAttribute('opacity', opacity);
    }
  }));
}

